{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.correct_price as with price as ( select distinct LEFT(value:sku::STRING, LENGTH(value:sku::STRING) - POSITION(\'-\' in REVERSE(value:sku::STRING))) as sku_group, split_part(id,\'/\',-1) as id, ifnull(value:compareAtPrice::NUMBER,0)::int as compare_at_price, value:price::NUMBER::int as price from snitch_db.maplemonk.new_meafields_product_products_graph_ql, lateral flatten(input => parse_json(variants)) as value ), final_price1 as ( select sku_group, id, greatest(compare_at_price,price) AS db_original_price, CASE WHEN compare_at_price != 0 THEN LEAST(compare_at_price,price) ELSE GREATEST(price,compare_at_price) END AS db_slashed_price from price ) select sku_group, id, db_original_price as original_price, db_slashed_price as current_slashed_price, from final_price1 where sku_group not in (\'\',\'1290\') qualify row_number() over (partition by sku_group order by db_original_price desc) = 1 ; create or replace table snitch_DB.MAPLEMONK.Shopify_UTM_Parameters as select *, coalesce(ShopifyQL_Unmapped_Last_Source,Referrer_Name) as ShopifyQL_MAPPED_SOURCE, FirstVisit_UTM_Source as ShopifyQL_MAPPED_FIRSTCLICK_SOURCE from (select A.id ,A.name ,A.createdat ,replace(A.customerjourneysummary:\"momentsCount\",\'\"\',\'\') Moments_Count ,replace(A.customerjourneysummary:\"daysToConversion\",\'\"\',\'\') DaysToConvert ,replace(A.CUSTOMERJOURNEYSUMMARY:\"lastVisit\":\"utmParameters\":\"source\",\'\"\',\'\') LastVisit_UTM_Source ,replace(A.CUSTOMERJOURNEYSUMMARY:\"lastVisit\":\"utmParameters\":\"medium\",\'\"\',\'\') LastVisit_UTM_Medium ,replace(A.CUSTOMERJOURNEYSUMMARY:\"lastVisit\":\"source\",\'\"\',\'\') LastVisit_NON_UTM_Source ,replace(A.CUSTOMERJOURNEYSUMMARY:\"lastVisit\":\"utmParameters\":\"campaign\",\'\"\',\'\') LastVisit_UTM_Campaign ,replace(A.CUSTOMERJOURNEYSUMMARY:\"firstVisit\":\"utmParameters\":\"source\",\'\"\',\'\') FirstVisit_UTM_Source ,replace(A.CUSTOMERJOURNEYSUMMARY:\"firstVisit\":\"utmParameters\":\"medium\",\'\"\',\'\') FirstVisit_UTM_Medium ,replace(A.CUSTOMERJOURNEYSUMMARY:\"firstVisit\":\"utmParameters\":\"campaign\",\'\"\',\'\') FirstVisit_UTM_Campaign ,replace(B.Value:\"id\",\'gid://shopify/CustomerVisit/\',\'\') Moment_ID ,replace(B.value:\"utmParameters\":\"source\",\'\"\',\'\') Last_Moment_UTM_Source ,replace(B.value:\"utmParameters\":\"medium\",\'\"\',\'\') Last_Moment_UTM_Medium ,replace(B.value:\"utmParameters\":\"campaign\",\'\"\',\'\') Last_Moment_UTM_Campaign ,case when Moments_Count >1 then LastVisit_UTM_Source else FirstVisit_UTM_Source end CJSummary_utm_source ,referrerdisplaytext Referrer_Name ,customerjourneysummary ,customerjourney ,Last_Moment_UTM_medium ShopifyQL_Unmapped_Last_medium ,coalesce(Last_Moment_UTM_Source,LastVisit_NON_UTM_Source) ShopifyQL_Unmapped_Last_Source ,rank() over (partition by name order by MOMENT_ID desc) rw from (select id, name, createdat, customerjourney, customerjourneysummary, referrerurl, referralcode, referrerdisplaytext, landingpageurl, LANDINGPAGEDISPLAYTEXT from Snitch_db.MAPLEMONK.shopifyindia_utm_parameters ) A, lateral flatten (INPUT => customerjourney:\"moments\") B ) where rw=1 union all select *, coalesce(ShopifyQL_Unmapped_Last_Source,Referrer_Name) as ShopifyQL_MAPPED_SOURCE, FirstVisit_UTM_Source as ShopifyQL_MAPPED_FIRSTCLICK_SOURCE from (select A.id ,A.name ,A.createdat ,coalesce(CUSTOMERJOURNEYSUMMARY:\"momentsCount\":\"count\" ,customerjourneysummary:\"momentsCount\") Moments_Count ,replace(A.customerjourneysummary:\"daysToConversion\",\'\"\',\'\') DaysToConvert ,replace(A.CUSTOMERJOURNEYSUMMARY:\"lastVisit\":\"utmParameters\":\"source\",\'\"\',\'\') LastVisit_UTM_Source ,replace(A.CUSTOMERJOURNEYSUMMARY:\"lastVisit\":\"utmParameters\":\"medium\",\'\"\',\'\') LastVisit_UTM_Medium ,replace(A.CUSTOMERJOURNEYSUMMARY:\"lastVisit\":\"source\",\'\"\',\'\') LastVisit_NON_UTM_Source ,replace(A.CUSTOMERJOURNEYSUMMARY:\"lastVisit\":\"utmParameters\":\"campaign\",\'\"\',\'\') LastVisit_UTM_Campaign ,replace(A.CUSTOMERJOURNEYSUMMARY:\"firstVisit\":\"utmParameters\":\"source\",\'\"\',\'\') FirstVisit_UTM_Source ,replace(A.CUSTOMERJOURNEYSUMMARY:\"firstVisit\":\"utmParameters\":\"medium\",\'\"\',\'\') FirstVisit_UTM_Medium ,replace(A.CUSTOMERJOURNEYSUMMARY:\"firstVisit\":\"utmParameters\":\"campaign\",\'\"\',\'\') FirstVisit_UTM_Campaign ,replace(B.Value:\"id\",\'gid://shopify/CustomerVisit/\',\'\') Moment_ID ,replace(B.value:\"utmParameters\":\"source\",\'\"\',\'\') Last_Moment_UTM_Source ,replace(B.value:\"utmParameters\":\"medium\",\'\"\',\'\') Last_Moment_UTM_Medium ,replace(B.value:\"utmParameters\":\"campaign\",\'\"\',\'\') Last_Moment_UTM_Campaign ,case when Moments_Count >1 then LastVisit_UTM_Source else FirstVisit_UTM_Source end CJSummary_utm_source ,referrerdisplaytext Referrer_Name ,customerjourneysummary ,customerjourney ,Last_Moment_UTM_medium ShopifyQL_Unmapped_Last_medium ,coalesce(Last_Moment_UTM_Source,LastVisit_NON_UTM_Source) ShopifyQL_Unmapped_Last_Source ,rank() over (partition by name order by MOMENT_ID desc) rw from (select id, name, createdat, customerjourney, customerjourneysummary, referrerurl, referralcode, referrerdisplaytext, landingpageurl, LANDINGPAGEDISPLAYTEXT from Snitch_db.MAPLEMONK.shopifyindia_20240809_utm_parameters ) A, lateral flatten (INPUT => customerjourney:\"moments\") B ) where rw = 1 and lastvisit_non_utm_source <> \'https://api.razorpay.com/\' union all select *, coalesce(ShopifyQL_Unmapped_Last_Source,Referrer_Name) as ShopifyQL_MAPPED_SOURCE, FirstVisit_UTM_Source as ShopifyQL_MAPPED_FIRSTCLICK_SOURCE from (select A.id ,A.name ,A.createdat ,coalesce(CUSTOMERJOURNEYSUMMARY:\"momentsCount\":\"count\" ,customerjourneysummary:\"momentsCount\") Moments_Count ,replace(A.customerjourneysummary:\"daysToConversion\",\'\"\',\'\') DaysToConvert ,replace(A.CUSTOMERJOURNEYSUMMARY:\"lastVisit\":\"utmParameters\":\"source\",\'\"\',\'\') LastVisit_UTM_Source ,replace(A.CUSTOMERJOURNEYSUMMARY:\"lastVisit\":\"utmParameters\":\"medium\",\'\"\',\'\') LastVisit_UTM_Medium ,replace(A.CUSTOMERJOURNEYSUMMARY:\"lastVisit\":\"source\",\'\"\',\'\') LastVisit_NON_UTM_Source ,replace(A.CUSTOMERJOURNEYSUMMARY:\"lastVisit\":\"utmParameters\":\"campaign\",\'\"\',\'\') LastVisit_UTM_Campaign ,replace(A.CUSTOMERJOURNEYSUMMARY:\"firstVisit\":\"utmParameters\":\"source\",\'\"\',\'\') FirstVisit_UTM_Source ,replace(A.CUSTOMERJOURNEYSUMMARY:\"firstVisit\":\"utmParameters\":\"medium\",\'\"\',\'\') FirstVisit_UTM_Medium ,replace(A.CUSTOMERJOURNEYSUMMARY:\"firstVisit\":\"utmParameters\":\"campaign\",\'\"\',\'\') FirstVisit_UTM_Campaign ,replace(B.Value:\"id\",\'gid://shopify/CustomerVisit/\',\'\') Moment_ID ,replace(B.value:\"utmParameters\":\"source\",\'\"\',\'\') Last_Moment_UTM_Source ,replace(B.value:\"utmParameters\":\"medium\",\'\"\',\'\') Last_Moment_UTM_Medium ,replace(B.value:\"utmParameters\":\"campaign\",\'\"\',\'\') Last_Moment_UTM_Campaign ,case when Moments_Count >1 then LastVisit_UTM_Source else FirstVisit_UTM_Source end CJSummary_utm_source ,referrerdisplaytext Referrer_Name ,customerjourneysummary ,customerjourney ,Last_Moment_UTM_medium ShopifyQL_Unmapped_Last_medium ,coalesce(Last_Moment_UTM_Source,LastVisit_NON_UTM_Source) ShopifyQL_Unmapped_Last_Source ,rank() over (partition by name order by MOMENT_ID desc) rw from (select id, name, createdat, customerjourney, customerjourneysummary, referrerurl, referralcode, referrerdisplaytext, landingpageurl, LANDINGPAGEDISPLAYTEXT from Snitch_db.MAPLEMONK.shopifyindia_20240809_utm_parameters ) A, lateral flatten (INPUT => customerjourney:\"moments\") B ) where rw = 2 and lastvisit_non_utm_source = \'https://api.razorpay.com/\' ; create or replace table snitch_db.maplemonk.GOKWIK_SOURCE as With GO_KWIK as ( WITH utm_source_cte AS ( SELECT S.id, UPPER(A.value:\"value\") AS gokwik_utm_source FROM (select * from (select *, row_number() over (partition by name order by updated_at) rw from Snitch_db.MAPLEMONK.SHOPIFYINDIA_ORDERS_SCD) where rw = 1) S, LATERAL FLATTEN(INPUT => note_attributes, outer => true) A WHERE (LOWER(S.note_attributes) LIKE \'%gokwik%\' or LOWER(S.note_attributes) LIKE \'%trackier%\') AND LOWER(A.value:\"name\") = \'utm_source\' ), utm_medium_cte AS ( SELECT S.id, UPPER(A.value:\"value\") AS gokwik_utm_medium FROM (select * from (select *, row_number() over (partition by name order by updated_at) rw from Snitch_db.MAPLEMONK.SHOPIFYINDIA_ORDERS_SCD) where rw = 1) S, LATERAL FLATTEN(INPUT => note_attributes, outer => true) A WHERE (LOWER(S.note_attributes) LIKE \'%gokwik%\' or LOWER(S.note_attributes) LIKE \'%trackier%\') AND LOWER(A.value:\"name\") = \'utm_medium\' ), utm_campaign_cte AS ( SELECT S.id, UPPER(A.value:\"value\") AS gokwik_utm_campaign FROM (select * from (select *, row_number() over (partition by name order by updated_at) rw from Snitch_db.MAPLEMONK.SHOPIFYINDIA_ORDERS_SCD) where rw = 1) S, LATERAL FLATTEN(INPUT => note_attributes, outer => true) A WHERE (LOWER(S.note_attributes) LIKE \'%gokwik%\' or LOWER(S.note_attributes) LIKE \'%trackier%\') AND LOWER(A.value:\"name\") = \'utm_campaign\' ) SELECT S.id, S.note_attributes, case when lower(campaign_cte.gokwik_utm_campaign) like \'%trackier%\' then \'JIO\' else source_cte.gokwik_utm_source end AS GOKWIK_UTM_SOURCE, medium_cte.gokwik_utm_medium AS GOKWIK_UTM_medium, campaign_cte.gokwik_utm_campaign AS GOKWIK_UTM_campaign FROM (select * from (select *, row_number() over (partition by name order by updated_at) rw from Snitch_db.MAPLEMONK.SHOPIFYINDIA_ORDERS_SCD) where rw = 1) S LEFT JOIN utm_source_cte source_cte ON S.id = source_cte.id LEFT JOIN utm_medium_cte medium_cte ON S.id = medium_cte.id LEFT JOIN utm_campaign_cte campaign_cte ON S.id = campaign_cte.id WHERE (LOWER(S.note_attributes) LIKE \'%gokwik%\' or LOWER(S.note_attributes) LIKE \'%trackier%\') AND coalesce(source_cte.gokwik_utm_source, campaign_cte.GOKWIK_UTM_campaign) IS NOT NULL ) Select * from GO_KWIK ; create or replace table snitch_db.maplemonk.simpl_SOURCE as With simpl as ( WITH utm_source_cte AS ( SELECT S.id, UPPER(A.value:\"value\") AS simpl_utm_source FROM (select * from (select *, row_number() over (partition by name order by updated_at) rw from Snitch_db.MAPLEMONK.SHOPIFYINDIA_ORDERS_SCD) where rw = 1) S, LATERAL FLATTEN(INPUT => note_attributes) A WHERE (LOWER(S.PAYMENT_GATEWAY_NAMES) LIKE \'%simpl%\' or lower(tags) like \'%simpl%\') AND LOWER(A.value:\"name\") = \'utm_source\' ), utm_medium_cte AS ( SELECT S.id, UPPER(A.value:\"value\") AS simpl_utm_medium FROM (select * from (select *, row_number() over (partition by name order by updated_at) rw from Snitch_db.MAPLEMONK.SHOPIFYINDIA_ORDERS_SCD) where rw = 1) S, LATERAL FLATTEN(INPUT => note_attributes) A WHERE (LOWER(S.PAYMENT_GATEWAY_NAMES) LIKE \'%simpl%\' or lower(tags) like \'%simpl%\') AND LOWER(A.value:\"name\") = \'utm_medium\' ), utm_campaign_cte AS ( SELECT S.id, UPPER(A.value:\"value\") AS simpl_utm_campaign FROM (select * from (select *, row_number() over (partition by name order by updated_at) rw from Snitch_db.MAPLEMONK.SHOPIFYINDIA_ORDERS_SCD) where rw = 1) S, LATERAL FLATTEN(INPUT => note_attributes) A WHERE (LOWER(S.PAYMENT_GATEWAY_NAMES) LIKE \'%simpl%\' or lower(tags) like \'%simpl%\') AND LOWER(A.value:\"name\") = \'utm_campaign\' ) SELECT S.id, S.note_attributes, s.payment_gateway_names, source_cte.simpl_utm_source AS simpl_UTM_SOURCE, medium_cte.simpl_utm_medium AS simpl_UTM_medium, campaign_cte.simpl_utm_campaign AS simpl_UTM_campaign FROM (select * from (select *, row_number() over (partition by name order by updated_at) rw from Snitch_db.MAPLEMONK.SHOPIFYINDIA_ORDERS_SCD) where rw = 1) S LEFT JOIN utm_source_cte source_cte ON S.id = source_cte.id LEFT JOIN utm_medium_cte medium_cte ON S.id = medium_cte.id LEFT JOIN utm_campaign_cte campaign_cte ON S.id = campaign_cte.id WHERE (LOWER(S.PAYMENT_GATEWAY_NAMES) LIKE \'%simpl%\' or lower(tags) like \'%simpl%\') AND source_cte.simpl_utm_source IS NOT NULL ) Select * from simpl ; CREATE OR REPLACE TABLE Snitch_db.maplemonk.Shopify_All_customers AS select *,\'Shopify_India\' AS Shop_Name from Snitch_db.maplemonk.shopifyindia_customers; CREATE OR REPLACE TABLE Snitch_db.MAPLEMONK.Shopify_All_orders AS select o.* ,UPPER(ShopifyQL.shopifyql_mapped_source) shopifyql_mapped_source ,UPPER(ShopifyQL.FIRSTVISIT_UTM_SOURCE) Shopifyql_FIRSTVISIT_UTM_SOURCE ,UPPER(ShopifyQL.LAST_MOMENT_UTM_SOURCE) Shopifyql_LAST_MOMENT_UTM_SOURCE ,UPPER(ShopifyQL.LastVisit_NON_UTM_Source) Shopifyql_LAST_VISIT_NON_UTM_SOURCE ,upper(ShopifyQL.LastVisit_UTM_Campaign) Shopifyql_LAST_VISIT_UTM_CAMPAIGN ,upper(ShopifyQL.LastVisit_UTM_Medium) Shopifyql_LAST_VISIT_UTM_Medium ,UPPER(ShopifyQL.LAST_MOMENT_UTM_MEDIUM) Shopifyql_LAST_MOMENT_UTM_MEDIUM ,UPPER(ShopifyQL.FIRSTVISIT_UTM_MEDIUM) Shopifyql_FIRSTVISIT_UTM_MEDIUM ,UPPER(ShopifyQL.FirstVisit_UTM_Campaign) Shopifyql_FIRSTVISIT_UTM_CAMPAIGN ,UPPER(ShopifyQL.LAST_MOMENT_UTM_CAMPAIGN) Shopifyql_LAST_MOMENT_UTM_CAMPAIGN ,UPPER(ShopifyQL.ShopifyQL_MAPPED_FIRSTCLICK_SOURCE) ShopifyQL_MAPPED_FIRSTCLICK_SOURCE ,div0(ShopifyQL.MOMENTS_COUNT,count(1) over (partition by O.name order by 1)) MOMENTS_COUNT ,div0(ShopifyQL.DAYSTOCONVERT,count(1) over (partition by O.name order by 1)) DAYSTOCONVERT ,UPPER(GOKWIK.GOKWIK_UTM_SOURCE) GOKWIK_MAPPED_SOURCE ,UPPER(simpl.SIMPL_UTM_SOURCE) SIMPL_MAPPED_SOURCE ,UPPER(GOKWIK.GOKWIK_UTM_MEDIUM) GOKWIK_MAPPED_medium ,UPPER(simpl.SIMPL_UTM_MEDIUM) SIMPL_MAPPED_medium ,UPPER(GOKWIK.GOKWIK_UTM_CAMPAIGN) GOKWIK_MAPPED_campaign ,UPPER(simpl.SIMPL_UTM_CAMPAIGN) SIMPL_MAPPED_campaign ,UPPER(Referrer_Name) Referrer_Name ,Upper(coalesce(shopifyql_mapped_source,GOKWIK_UTM_SOURCE,simpl_UTM_SOURCE,\'Direct\')) FINAL_UTM_SOURCE ,upper(coalesce(Shopifyql_LAST_MOMENT_UTM_MEDIUM, Shopifyql_LAST_VISIT_UTM_Medium, Shopifyql_FIRSTVISIT_UTM_MEDIUM, GOKWIK_MAPPED_medium, SIMPL_MAPPED_medium)) FINAL_UTM_MEDIUM ,upper(coalesce(Shopifyql_LAST_MOMENT_UTM_CAMPAIGN, Shopifyql_LAST_VISIT_UTM_CAMPAIGN, Shopifyql_FIRSTVISIT_UTM_CAMPAIGN, GOKWIK_MAPPED_CAMPAIGN, SIMPL_MAPPED_CAMPAIGN)) FINAL_UTM_CAMPAIGN ,\'Shopify_India\' AS Shop_Name, CASE when o.created_at::date < \'2022-06-16\' and s.amount = 0 then \'prepaid\' when o.created_at::date < \'2022-06-16\' and s.amount <> 0 then \'cod\' end as payment_mode from (select * from Snitch_db.MAPLEMONK.SHOPIFYINDIA_ORDERS where name != \'2222802\') o LEFT JOIN (select distinct _AIRBYTE_SHOPIFYINDIA_ORDERS_HASHID,presentment_money:amount amount from Snitch_db.maplemonk.SHOPIFYINDIA_ORDERS_TOTAL_SHIPPING_PRICE_SET) s on s._AIRBYTE_SHOPIFYINDIA_ORDERS_HASHID = o._AIRBYTE_shopifyindia_ORDERS_HASHID left join snitch_db.maplemonk.Shopify_UTM_Parameters ShopifyQL on O.name = ShopifyQL.name left join snitch_db.maplemonk.GOKWIK_SOURCE GOKWIK on O.ID = GOKWIK.ID left join snitch_db.maplemonk.simpl_SOURCE simpl on O.ID = simpl.ID ; ALTER TABLE Snitch_db.maplemonk.Shopify_All_orders RENAME COLUMN _AIRBYTE_SHOPIFYINDIA_ORDERS_HASHID to _AIRBYTE_ORDERS_HASHID; CREATE OR REPLACE TABLE Snitch_db.maplemonk.Shopify_All_products AS select *,\'Shopify_India\' AS Shop_Name from Snitch_db.maplemonk.shopifyindia_products ; ALTER TABLE Snitch_db.maplemonk.Shopify_All_products RENAME COLUMN _AIRBYTE_SHOPIFYINDIA_PRODUCTS_HASHID to _AIRBYTE_PRODUCTS_HASHID; CREATE OR REPLACE TABLE Snitch_db.maplemonk.Shopify_All_products_variants AS select *,\'Shopify_India\' AS Shop_Name from Snitch_db.maplemonk.shopifyindia_products_variants ; ALTER TABLE Snitch_db.maplemonk.Shopify_All_products_variants RENAME COLUMN _AIRBYTE_SHOPIFYINDIA_PRODUCTS_HASHID to _AIRBYTE_PRODUCTS_HASHID; CREATE OR REPLACE TABLE Snitch_db.maplemonk.Shopify_All_customers_addresses AS select *,\'Shopify_India\' AS Shop_Name from Snitch_db.maplemonk.shopifyindia_customers_addresses ; CREATE OR REPLACE TABLE Snitch_db.maplemonk.Shopify_All_orders_items_discount AS SELECT order_id, LINE_ITEM_ID, SUM(B.VALUE:amount::FLOAT) AS DISCOUNT FROM( SELECT id AS order_id, A.VALUE:id AS LINE_ITEM_ID, A.VALUE:discount_allocations AS discount_allocations FROM Snitch_db.maplemonk.Shopify_All_orders, LATERAL FLATTEN (INPUT => LINE_ITEMS)A)x,LATERAL FLATTEN (INPUT => x.discount_allocations)B GROUP BY ORDER_ID, LINE_ITEM_ID; CREATE OR REPLACE TABLE Snitch_db.maplemonk.Shopify_All_orders_items_discount_exchange AS select order_id, line_item_id, discount exchange_discount from (SELECT order_id, LINE_ITEM_ID, B.VALUE:amount::FLOAT AS DISCOUNT, B.value:discount_application_index position, row_number() over (partition by order_id,LINE_ITEM_ID order by position desc) rw FROM( SELECT id AS order_id, A.VALUE:id AS LINE_ITEM_ID, A.VALUE:discount_allocations AS discount_allocations FROM Snitch_db.maplemonk.Shopify_All_orders, LATERAL FLATTEN (INPUT => LINE_ITEMS)A where tags like \'%Ecoreturns-Exchange%\' )x,LATERAL FLATTEN (INPUT => x.discount_allocations)B )where rw=1 ; CREATE OR REPLACE TABLE snitch_db.maplemonk.Shopify_All_orders_items_tax AS SELECT order_id, LINE_ITEM_ID, SUM(B.VALUE:price::FLOAT) AS TAX, sum(B.VALUE:rate::float) as Tax_Rate FROM( SELECT id AS order_id, A.VALUE:id AS LINE_ITEM_ID, A.VALUE:tax_lines AS tax_lines FROM snitch_db.maplemonk.Shopify_All_orders, LATERAL FLATTEN (INPUT => LINE_ITEMS)A)x,LATERAL FLATTEN (INPUT => x.tax_lines)B GROUP BY order_id, LINE_ITEM_ID; CREATE OR REPLACE TABLE Snitch_db.maplemonk.Shopify_All_Refunds AS SELECT Name, ID AS Order_ID, Shop_name, C.value:line_item_id AS line_item_id, SUM(C.VALUE:quantity) AS quantity, SUM(C.VALUE:subtotal) AS subtotal FROM Snitch_db.maplemonk.Shopify_All_orders, LATERAL FLATTEN(INPUT => refunds)A, LATERAL FLATTEN(INPUT=>A.value)B, LATERAL FLATTEN(INPUT => B.value) C WHERE C.value:line_item_id IS NOT null GROUP BY Name, ID, Shop_name, C.value:line_item_id ; CREATE OR REPLACE TABLE snitch_db.maplemonk.Shopify_All_discount_codes AS select ID, CODE from ( SELECT id, replace(A.value:code , \'\"\',\'\') code, row_number() over (partition by id order by code) rw FROM snitch_db.maplemonk.Shopify_All_orders, LATERAL FLATTEN (INPUT => discount_codes) A ) where rw=1; CREATE OR REPLACE TABLE Snitch_db.maplemonk.Shopify_All_orders_items AS WITH CTE AS (SELECT SHOP_NAME, note, ID::VARCHAR(16777216) AS ORDER_ID, NAME AS ORDER_NAME, CUSTOMER, A.VALUE:id AS LINE_ITEM_ID, A.VALUE:sku::STRING AS SKU, A.VALUE:product_id::STRING AS PRODUCT_ID, A.VALUE:title::STRING AS PRODUCT_NAME, app_id, coalesce(phone, replace(customer:default_address:phone,\'\"\',\'\')) phone, coalesce(email, replace(customer:email,\'\"\',\'\')) email, replace(customer:default_address:zip,\'\"\',\'\') pincode, replace(customer:default_address:id,\'\"\',\'\') shopify_customer_id, CURRENCY, tags, coalesce(gateway,payment_gateway_names[0]) as gateway, note_attributes, source_name, CASE WHEN cancelled_at IS NOT NULL THEN \'CANCELLED\' ELSE \'Shopify_Processed\' END AS order_status, CREATED_AT::DATETIME AS order_timestamp, A.VALUE:price::FLOAT * A.VALUE:quantity::FLOAT AS LINE_ITEM_SALES, (TOTAL_SHIPPING_PRICE_SET:presentment_money:amount::FLOAT/ COUNT(ORDER_ID) OVER(PARTITION BY ORDER_ID ORDER BY ORDER_ID)) AS SHIPPING_PRICE, A.VALUE:quantity::FLOAT as QUANTITY, \'Shopify\' AS Source, LANDING_SITE, REFERRING_SITE, payment_mode, MOMENTS_COUNT, DAYSTOCONVERT, SHOPIFYQL_FIRSTVISIT_UTM_SOURCE, SHOPIFYQL_MAPPED_SOURCE, SHOPIFYQL_LAST_MOMENT_UTM_SOURCE, Shopifyql_LAST_VISIT_NON_UTM_SOURCE, Shopifyql_LAST_MOMENT_UTM_MEDIUM, Shopifyql_FIRSTVISIT_UTM_MEDIUM, ShopifyQL_MAPPED_FIRSTCLICK_SOURCE, Shopifyql_FIRSTVISIT_UTM_CAMPAIGN, Shopifyql_LAST_VISIT_UTM_CAMPAIGN, FINAL_UTM_SOURCE, FINAL_UTM_MEDIUM, FINAL_UTM_CAMPAIGN, Referrer_Name, GOKWIK_MAPPED_SOURCE, payment_gateway_names FROM Snitch_db.maplemonk.Shopify_All_orders, LATERAL FLATTEN (INPUT => LINE_ITEMS)A) SELECT CTE.*, DC.code discount_code, IFNULL(T.TAX_RATE,0) AS TAX_RATE, IFNULL(T.TAX,0) AS TAX, IFNULL(D.DISCOUNT,0) AS DISCOUNT, IFnull(DE.EXCHANGE_DISCOUNT,0) as EXCHANGE_DISCOUNT, CASE when T.TAX=0 then IFNULL(D.DISCOUNT,0) else IFNULL(D.DISCOUNT,0)/(1+IFNULL(T.TAX_RATE,0)) end AS DISCOUNT_BEFORE_TAX, CTE.LINE_ITEM_SALES - IFNULL(D.DISCOUNT,0) + IFNULL(CTE.SHIPPING_PRICE,0) AS NET_SALES, CTE.LINE_ITEM_SALES - IFNULL(D.DISCOUNT,0) as Gross_Sales, case when T.TAX=0 then (CTE.LINE_ITEM_SALES) - IFNULL(D.DISCOUNT,0) + IFNULL(T.TAX,0) + CTE.SHIPPING_PRICE else (CTE.LINE_ITEM_SALES/(1+IFNULL(T.TAX_RATE,0))) - (IFNULL(D.DISCOUNT,0)/(1+IFNULL(T.TAX_RATE,0))) + IFNULL(T.TAX,0) + CTE.SHIPPING_PRICE end AS TOTAL_SALES, CTE.LINE_ITEM_SALES/(1+IFNULL(T.TAX_RATE,0)) AS GROSS_SALES_BEFORE_TAX, CASE WHEN R.QUANTITY IS NOT NULL THEN 1 ELSE 0 END AS IS_REFUND, div0(ifnull(ld.amount,0),count(*) over(partition by cte.order_id)) as Loyalty_Discount, case when cs.shopify_user_id is null then \'NO\' else \'YES\' end as Loyalty_Customer FROM CTE LEFT JOIN Snitch_db.maplemonk.Shopify_All_orders_items_tax T ON CTE.ORDER_ID = T.ORDER_ID AND CTE.LINE_ITEM_ID = T.LINE_ITEM_ID LEFT JOIN Snitch_db.maplemonk.Shopify_All_orders_items_discount D ON CTE.ORDER_ID = D.ORDER_ID AND CTE.LINE_ITEM_ID = D.LINE_ITEM_ID LEFT JOIN Snitch_db.maplemonk.Shopify_All_orders_items_discount_exchange DE ON CTE.ORDER_ID = DE.ORDER_ID AND CTE.LINE_ITEM_ID = DE.LINE_ITEM_ID LEFT JOIN Snitch_db.maplemonk.Shopify_All_Refunds R ON CTE.ORDER_ID = R.ORDER_ID AND CTE.LINE_ITEM_ID = R.LINE_ITEM_ID left join snitch_db.maplemonk.Shopify_All_discount_codes DC on CTE.order_id = DC.id left join ( select try_cast(SHOPIFY_ORDER_ID as int)::string Order_id ,abs(sum(ifnull(amount,0))) amount from snitch_db.maplemonk.s3_bucket_wallet_transaction_db where SHOPIFY_ORDER_NUMBER != \'\' and type = \'POINTS_DEBIT\' and reason = \'Purchase : Online\' and membership_plan = \'SILVER\' group by 1 )ld on cte.Order_id = ld.Order_id left join ( select shopify_user_id, sum(ifnull(points_balance,0)) as points_balance from snitch_db.maplemonk.s3_bucket_wallet_db where membership_plan = \'SILVER\' group by 1 )cs on replace(trim(cte.CUSTOMER:id::int),\' \',\'\') = replace(trim(shopify_user_id),\' \',\'\') ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            